const cf=d=>INQ.filter(i=>i.d==d&&i.st!="Declined").length>1,now=new Date(),y=now.getFullYear(),mo=now.getMonth(),dim=new Date(y,mo+1,0).getDate(),f0=new Date(y,mo,1).getDay();let cal=["S","M","T","W","T","F","S"].map(x=>`<button class="h" disabled>${x}</button>`).join("")+"<span></span>".repeat(f0);
