scan(v){const code=v||val("code");referenceRequest("/admin/api/reference/barcode/lookup","POST",{barcode:code}).then(data=>{const i=ing(data.ingredient.id)||{id:String(data.ingredient.id),n:data.ingredient.name,u:data.ingredient.unit,c:data.unit_cost||0,cw:false,bin:data.storage_zone||"",b:[],s:data.current_stock||0};const p=PO.find(x=>x.item==data.purchase_order_item_id);cur={i,l:{id:i.id,item:data.purchase_order_item_id,no:data.purchase_order.reference,sup:data.purchase_order.supplier,ord:data.purchase_order.ordered_quantity,rec:data.purchase_order.received_quantity}};bmsg=["ok","Package found on "+data.purchase_order.reference+". Check the details, then confirm."];R()}).catch(e=>{cur=null;bmsg=["er",e.message];R()})},
